import {ECHO_EVENTS,BENEFIT_NAMES} from './echoes-data.js';
import {ITEMS,REGIONS,CROPS,BUILDINGS} from './data.js';
import {RESIDENTS} from './expansion-data.js';
import {CHAPTERS,ARCS} from './rebuild-data.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,id='',reason='',primary=false,extra='')=>`<button data-action="${action}" data-id="${esc(id)}" ${reason?'disabled aria-disabled="true"':''} ${primary?'class="primary"':''} ${extra}>${esc(label)}</button>${reason?`<small class="echo-reason">${esc(reason)}</small>`:''}`;
const bundle=b=>Object.entries(b).map(([id,n])=>ITEMS[id].name+'×'+n).join('、')||'无';
const card=(title,body,extra='')=>`<section class="rebuild-card ${extra}"><h3>${title}</h3>${body}</section>`;
const stateName=a=>!a?'尚未解锁':a.status==='active'?'进行中':a.status==='resolved'?'已解决':a.status==='postponed'?'已延期':'已预告';
export function renderUnifiedGoal(e){const g=e.supplyGoal(),q=e.currentRebuildTask(),rows=e.goalMaterials(),target=q&&e.taskDestination(q.id),ready=q&&e.taskReady(q.id),requirements=q?e.taskRequirements(q.id):[];return card('下一步 · '+esc(g.title),`<p class="echo-lead">${esc(g.use)}</p><div class="echo-metrics"><span>主线<b>${e.r.claimed.length}/16</b></span><span>成品待领<b>${e.c.production.filter(j=>j.ready).length}</b></span><span>当前事件<b>${e.activeEvents().length}/2</b></span></div><div class="button-row">${e.u.pin==='auto'&&ready?button(e.s.region==='farm'?'rClaim':'rHome',e.s.region==='farm'?'确认成果，推进下一步':'回营地确认成果',q.id,'',true):button('rOpen','前往这一步的操作入口',g.where,'',true)}${target?button('rTrack','标记主线位置',q.id):''}${button('rTab','营地消息','events')}</div><details class="echo-details"><summary>备料与完成条件 · ${rows.filter(r=>r.missing).length}种材料尚缺</summary><div class="echo-materials">${rows.map(r=>`<div><b>${ITEMS[r.id].name}</b><span>${r.have}/${r.need} · ${r.missing?'缺'+r.missing:'已备齐'}${r.pending?' · 在制'+r.pending:''}</span><p>${esc(r.source.text)}</p>${g.local?`<p>随身${r.carried}/${r.need}</p>${button('sPack','从仓库装够',r.id,e.s.region!=='farm'?'返回农场装包':'')}`:''}${button('rOpen','查看来源',r.source.where)}</div>`).join('')}</div>${requirements.length?`<ul class="rebuild-checklist">${requirements.map(r=>`<li>${r.pass?'✓':'○'} ${esc(r.label)}</li>`).join('')}</ul>`:'<p>选择长期合同、地区建设或事件，继续经营。</p>'}</details><details class="echo-details"><summary>调整这次的备料目标</summary><label>目标<select id="supply-goal">${e.goalOptions().map(o=>`<option value="${o.id}" ${o.id===e.u.pin?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label>${button('sPin','钉住目标')}${e.u.pin!=='auto'?button('sFollow','跟随主线'):''}</details><div class="echo-chapters">${CHAPTERS.map((c,i)=>`<span class="${e.r.claimed.length>=(i+1)*4?'done':''}">${i+1} ${c.name} · ${Math.max(0,Math.min(4,e.r.claimed.length-i*4))}/4</span>`).join('')}</div>`,'echo-main');}
export function renderEventSummary(e){const live=e.activeEvents(),next=ECHO_EVENTS.find(d=>e.v.records[d.id]?.status==='forecast');return card('营地消息',`<p>${live.length?'正在处理'+live.length+'件事；可以先完成一件，也可以延期。':next?'下一件可参与：'+esc(next.name):'消息会随前哨、居民、设备和调查进度解锁。'}</p>${live.map(d=>{const a=e.v.records[d.id],st=e.echoStep(d.id);return `<div class="echo-summary"><b>${d.name}</b><span>${st?esc(st.title):'选择行动路线'}${a.remaining?' · '+Math.ceil(a.remaining)+'游戏分钟':''}</span>${button('eFocus','查看并准备',d.id)}</div>`;}).join('')}${button('rTab','查看营地消息','events')}`);}
export function renderEvents(e,ui={}){
 e.ensureEchoForecasts();const filter=ui.eventFilter||'relevant';
 const list=ECHO_EVENTS.filter(d=>filter==='all'||filter==='finished'&&e.v.records[d.id]?.status==='resolved'||filter==='relevant'&&e.v.records[d.id]&&e.v.records[d.id].status!=='resolved');
 list.sort((a,b)=>Number(e.v.records[b.id]?.status==='active')-Number(e.v.records[a.id]?.status==='active'));
 const special=['services','history'].includes(ui.eventId),focus=special?ui.eventId:list.find(d=>d.id===ui.eventId)?.id||list[0]?.id;
 const selected=ECHO_EVENTS.find(d=>d.id===focus);
 const row=(id,title,sub)=>`<button class="manual-row ${focus===id?'selected':''}" data-action="eSelect" data-id="${id}" aria-pressed="${focus===id}"><b>${esc(title)}</b><small>${esc(sub)}</small><span aria-hidden="true">›</span></button>`;
 const body=focus==='services'?renderEchoServices(e):focus==='history'?renderEchoHistory(e):selected?renderEventCard(e,selected,true):'<p>当前没有待处理消息。切换“全部”查看解锁条件。</p>';
 return `<section class="manual-list event-list" aria-label="营地事件列表"><div class="list-heading"><small>营地事件</small><h3>消息与机会</h3><p>进行中 ${e.activeEvents().length}/2 · 已获改装 ${Object.keys(e.v.benefits).length}</p></div><div class="echo-toolbar">${['relevant','all','finished'].map((v,i)=>button('eFilter',['当前','全部','已解决'][i],v,'',false,`aria-pressed="${v===filter}"`)).join('')}</div>${list.map(d=>row(d.id,d.name,stateName(e.v.records[d.id])+' · '+(e.echoStep(d.id)?.title||'查看投入与结果'))).join('')||'<p>此分类暂无消息。</p>'}<div class="manual-label">事件带来的变化</div>${row('services','营地服务与改装','已解锁的能力，继续用于经营')}${row('history','消息与结果档案','查看最近40条记录')}</section><section class="manual-detail" aria-label="事件详情" tabindex="-1"><header class="detail-heading"><button class="mobile-back" data-action="clBack">‹ 返回事件列表</button><small>营地事件 / ${selected?'消息':'档案'}</small><h3>${selected?esc(selected.name):focus==='services'?'营地服务与改装':focus==='history'?'消息与结果档案':'选择一条消息'}</h3></header><div class="detail-scroll"><p class="manual-purpose">最多同时参与两件；菜单与离线暂停等待。每条路线会改变后续能力，先看清投入再选择。</p>${body}</div></section>`;
}
function renderEventCard(e,d,focused){const a=e.v.records[d.id],o=d.options.find(o=>o.id===a?.choice),st=e.echoStep(d.id),loc=e.echoLocation(d.id),availability=e.eventAvailability(d.id),reason=e.echoActionReason(d.id),benefit=e.v.benefits[d.id];return `<article class="rebuild-card echo-event ${focused?'echo-focused':''}" id="event-${d.id}"><div class="echo-event-head"><div><h3>${esc(d.name)}</h3><p>${esc(d.hook)}</p></div><span class="echo-badge">${stateName(a)}</span></div><p>${esc(d.text)}</p>${a?.status==='active'?(!o?`<div class="echo-choice-grid">${d.options.map(op=>`<section><h4>${esc(op.label)}</h4><dl><dt>投入</dt><dd>${bundle(op.steps.reduce((b,s)=>{for(const [id,n]of Object.entries(s.cost))b[id]=(b[id]||0)+n;return b;},{}))}</dd><dt>行动</dt><dd>${op.steps.length}步骤 · ${op.steps.some(s=>s.kind==='fight')?'含战斗':'无需事件战斗'} · ${op.steps.reduce((n,s)=>n+(s.minutes||0),0)}游戏分钟等待</dd><dt>结果</dt><dd>${esc(op.result)}</dd></dl>${button('eChoose','采用这条路线',d.id+':'+op.id,'',true)}</section>`).join('')}</div>`:`<div class="echo-step"><small>路线：${esc(o.label)} · 步骤${Math.min(o.steps.length,a.stage+1)}/${o.steps.length}</small><h4>${esc(st?.title||'事件完成')}</h4><p>地点：${loc?REGIONS[loc.region].name+' · 地图事件标记':''}</p><p>本步消耗：${bundle(st?.cost||{})}${a.paid?' · 已投入，重试不再扣除':''}</p>${st&&['produce','harvest','fight','photo'].includes(st.kind)?`<p>本步行动进度：${a.progress}/${st.count||1} · ${st.kind==='produce'?'本阶段新加工并领取或入仓才计数':st.kind==='harvest'?'玩家和居民的新收获都计数':st.kind==='photo'?'相机取景要包含事件标记':'仅统计事件敌人'}</p>`:''}${a.remaining?`<progress value="${(st.minutes||0)-a.remaining}" max="${st.minutes||1}"></progress><p>还需${Math.ceil(a.remaining)}游戏分钟；可以种田、出门或在农舍休息。</p>`:''}<div class="button-row">${button('ePerform',st?.kind==='fight'&&!a.spawned?'准备好了，开始战斗':st?.kind==='wait'&&!a.remaining?'投入材料，开始工作':'完成现场行动',d.id,reason,true)}${button('eTrack','标记现场',d.id)}${e.s.region==='farm'&&loc?.region!=='farm'?button('ePack','装够本步材料',d.id):''}${button('eDefer','延期处理',d.id,a.spawned||a.remaining?'已开始的工作或战斗结束后可延期':'')}</div><p class="echo-outcome"><b>最终用途：</b>${esc(o.result)}</p></div>`):`<div class="button-row">${button('eAccept',a?.status==='resolved'?'再次参与':a?.status==='postponed'?'继续这件事':'接下这条消息',d.id,availability,true)}</div>`}${benefit?`<p class="echo-outcome"><b>已留下：${BENEFIT_NAMES[d.id]}</b> · ${esc(d.options.find(x=>x.id===benefit).result)}</p>`:''}<details><summary>行动计划与后续</summary>${d.options.map(op=>`<p><b>${op.label}</b>：${op.steps.map(s=>s.title).join(' → ')}。</p>`).join('')}<p>永久能力首次获得；重复完成只给消耗品与记录。${d.cooldown?'完成后'+d.cooldown+'天可以再次参加。':'此调查只完成一次。'}</p></details></article>`;}
export function renderEchoServices(e){const list=e.echoServices().filter(d=>d.unlock);return card('事件留下的服务与改装',list.map(d=>`<div class="echo-service"><div><b>${d.name}</b><p>${bundle(d.cost)} → ${bundle(d.reward)} · 每${d.period}天一次，回程奖励入仓</p></div>${button('eService','使用服务',d.id,e.serviceReason(d.id))}</div>`).join('')+(e.v.benefits.loadtest?`<div class="echo-service"><p>产线改装：3零件、1电路。当前${e.v.benefits.loadtest==='dispatch'?'四条调度':'12次保养'}。</p>${button('eRetrofit','切换调度 / 保养','loadtest:'+(e.v.benefits.loadtest==='dispatch'?'maintenance':'dispatch'))}</div>`:'')+(e.v.benefits.coldroom==='dismantle'?button('eRetrofit','重建冷藏服务 · 2零件、1电路','coldroom:restore'):'')||'<p>完成车队、医院、冷藏间或复兴事件后，服务会在这里开放。</p>');}
export function renderEchoHistory(e){return `<details class="rebuild-card echo-history"><summary>消息与结果档案 · 保留最近40条</summary><ol>${e.v.history.map(x=>`<li class="${x.tone}"><small>第${x.day}天</small> ${esc(x.text)}${ECHO_EVENTS.find(d=>x.text.includes(d.name))?button('eFocus','查看事件',ECHO_EVENTS.find(d=>x.text.includes(d.name)).id):''}</li>`).join('')||'<li>首次消息会从这里开始。</li>'}</ol></details>`;}
export function renderWorkReport(e){return card('居民工作日报',`<p>显示实际执行的岗位、资源变化和停工原因。夜班、护理与疲劳会影响后续工作。</p><div class="echo-work-grid">${e.c.residents.map(r=>{const w=e.v.work[r.id]||{},reason=e.residentWorkReason(r);return `<article><h4>${RESIDENTS[r.id].name} · ${({farmer:'种植',medic:'医疗',mechanic:'维修',guard:'守卫',rest:'休息'})[r.workRole||r.role]||'等待排班'}</h4><p>工作餐 ${r.fed?'✓ 已供应':'○ 尚缺'} · 疲劳${Math.round(r.fatigue)} · 床位${e.c.residents.indexOf(r)<e.residentsCapacity()?'✓':'○'}</p><p class="echo-status">${esc(reason)}</p><dl><dt>记录日期</dt><dd>第${w.day||e.s.day}天</dd><dt>已执行班次</dt><dd>${w.shifts||0}</dd><dt>实际产出</dt><dd>${bundle(w.outputs||{})}</dd><dt>实际投入</dt><dd>${bundle(w.inputs||{})}</dd><dt>服务</dt><dd>治疗${Math.round(w.healing||0)} · 修复耐久${Math.round(w.repairs||0)}</dd></dl><div class="button-row">${button('feedResidents','供应工作餐','',e.s.region==='farm'?'':'返回农场')}${button('rTool','调整岗位','camp:residents')}${button('rOpen','增加床位','build:')}</div><details><summary>人物成长与下一段生活</summary>${r.id==='cartographer'?'<p>在边境手册安排驻站制图或随队向导。工作需要床位、食物与休息。</p><button data-action="bView" data-id="life">安排柏岚的工作</button>':''}<ol class="echo-timeline">${(ARCS[r.id]||[]).map((a,i)=>`<li class="${e.r.arcs[r.id]>i?'done':''}">${e.r.arcs[r.id]>i?'✓':'○'} ${a.title}<small>${a.effect}</small></li>`).join('')}</ol><p>${e.r.arcs[r.id]>=3?'新的教学、导师或家书事件会继续人物生活。':'继续下面的个人愿望解锁工作能力。'}</p>${(({farmer:['classroom','letter'],medic:['nightclinic','letter'],mechanic:['loadtest','mentor','letter']})[r.id]||[]).map(id=>`<div class="echo-timeline-event"><span>${e.event(id).name} · ${stateName(e.v.records[id])}</span>${button('eFocus','查看这段生活',id)}</div>`).join('')}</details></article>`;}).join('')||'<p>先从住宅区接回阿禾。</p>'}</div>`);}
export function renderBattleReport(e){const b=e.v.lastReport;if(!b)return card('战后复盘','<p>普通尸潮、章节防守和防线演习完成后，都显示实际贡献和损坏位置。</p>');return card(esc(b.name)+' · '+(b.won?'守住了':'需要重新准备'),`<div class="echo-metrics"><span>击败<b>${b.kills}/${b.count}</b></span><span>塔楼击败<b>${b.towerKills}</b></span><span>陷阱击败<b>${b.trapKills}</b></span><span>料理减伤<b>${Math.round(b.foodSaved)}</b></span><span>维修耐久<b>${Math.round(b.repairs)}</b></span><span>受到伤害<b>${Math.round(b.damage)}</b></span></div><p>${b.won?'经营投入已经发挥作用。检查损坏并为下一轮补给。':'已完成工程和研究保留；先供应工作餐、补弹药，再修好损坏位置。事件战斗可回到原步骤重试。'}</p>${b.damaged.map((x,i)=>`<div class="echo-service"><span>${BUILDINGS[x.type].name} · 损失${Math.round(x.loss)}耐久</span>${button('eDamage','标记损坏位置',String(i))}${button('repair','维修',x.id,e.s.region==='farm'?'':'返回农场')}</div>`).join('')||'<p>没有记录到设施耐久损失。</p>'}<div class="button-row">${button('rOpen','加工弹药与料理','craft:')}${button('rTab','居民与工作餐','residents')}${button('rTab','查看可重试事件','events')}</div>`);}
export function renderFarmOverlay(e){return card('农田信息层',`<p>${esc(e.plotEstimate(e.nearestPlot(e.s.player,90)))}</p><p>水分、肥力、天气风险使用图标和文字显示。温室可以抵御恶劣天气；耐旱品种、水渠与净水研究能改善种植效率。</p><div class="button-row">${['none','water','soil','pollution','events'].map((v,i)=>button('eOverlay',['关闭','水分','肥力','天气风险','事件'][i],v,'',false,`aria-pressed="${v===e.v.overlay}"`)).join('')}</div>${e.v.benefits.secondreport==='plants'?`<p>两日建议：${e.forecast().slice(1).map(f=>'第'+f.day+'天 '+f.weather+'：'+(['酸雨','暴雨'].includes(f.weather)?'优先温室或耐旱品种':'安排缺口作物')).join('；')}</p>`:''}`);}
export function renderEchoMap(e,ui){return `${card('这次出门的目的',e.activeEvents().map(d=>{const loc=e.echoLocation(d.id);return loc?`<div class="echo-service"><div><b>${d.name}</b><p>${REGIONS[loc.region].name} · ${e.echoStep(d.id).title}<br>${loc.region===e.s.region?'同区距离'+Math.round(Math.hypot(loc.x-e.s.player.x,loc.y-e.s.player.y))+'步':'需要前往该地区'} · 现场消耗${bundle(e.echoStep(d.id).cost)}<br>随身：${Object.entries(e.echoStep(d.id).cost).map(([id,n])=>ITEMS[id].name+' '+e.quantityForCost(id,false)+'/'+n).join('、')||'无需材料'}</p></div>${button('eTrack','标记目标',d.id)}${button('eTravel','前往该地区',d.id,e.s.region===loc.region?'已在同一地区，沿标记步行':'')}</div>`:'';}).join('')||'<p>先在当前目标或营地消息选一个目的，再带上口粮、药品与弹药。</p>')}<p class="echo-status">${e.s.region!=='farm'?button('rHome','返回营地'):''}现场寄存：${e.v.caches.length}箱 · 可在原地取回；已恢复前哨提供安全补给，M地图可随时规划返程。</p>`;}
export function renderCargoSummary(e){const worn=(e.wornIds?.()||[]).filter(id=>e.s.inventory[id]===1).length;return `<div class="echo-storage-summary"><span>随身物品种类<b>${Object.keys(e.s.inventory).length-worn}/${e.capacity()-worn}</b></span><span>仓库物品种类<b>${Object.keys(e.s.storage).length}</b></span><span>现场寄存箱<b>${e.v.caches.length}</b></span></div>${e.v.caches.length?`<details><summary>仍在现场的物资</summary>${e.v.caches.map(c=>`<p>${REGIONS[c.region].name}：${bundle(c.items)} · 到寄存箱旁按E取回</p>`).join('')}</details>`:''}`;}
export function handleEchoAction(action,b,ctx){if(!action.startsWith('e')||['equip','equipSeed','export'].includes(action))return false;const {engine:e,ui,showMenu,closeMenu,renderMenu,save,toast}=ctx,id=b.dataset.id;let ok=true;
 if(action==='eSelect'){ui.eventId=id;ui.mobileDetail=true;renderMenu();return true;}
 if(action==='eFocus'){ui.mobileDetail=true;ui.eventId=id;ui.eventFilter=e.v.records[id]?.status==='resolved'?'finished':e.v.records[id]?'relevant':'all';showMenu('rebuild',{tab:'events'});return true;}
 if(action==='eFilter'){ui.mobileDetail=false;ui.eventFilter=id;ui.eventId=null;renderMenu();return true;}
 if(action==='eTrack'||action==='eTravel'){const loc=e.echoLocation(id);if(!loc)return true;ui.target={...loc,label:e.event(id).name};if(action==='eTravel'){if(e.travel(loc.region)){closeMenu();save();}}else if(loc.region===e.s.region)closeMenu();else showMenu('map');toast('已标记事件：'+e.event(id).name+' · '+REGIONS[loc.region].name);return true;}
 if(action==='eDamage'){const loc=e.v.lastReport?.damaged[Number(id)];if(loc){ui.target={region:'farm',x:loc.x,y:loc.y,label:'受损'+BUILDINGS[loc.type].name};closeMenu();}return true;}
 if(action==='eAccept')ok=e.acceptEvent(id);
 else if(action==='eChoose'){const [event,choice]=id.split(':');ok=e.chooseEcho(event,choice);ui.eventId=event;}
 else if(action==='ePerform'){ok=e.performEcho(id);if(ok&&e.eventRecord(id)?.spawned){closeMenu();save();return true;}if(ok&&e.eventRecord(id)?.status==='resolved'){ui.eventId=id;ui.eventFilter='finished';}}
 else if(action==='eDefer')ok=e.deferEcho(id);
 else if(action==='ePack')ok=e.packEcho(id);
 else if(action==='eService')ok=e.useEchoService(id);
 else if(action==='eRetrofit'){const [event,choice]=id.split(':');ok=e.retrofitEcho(event,choice);}
 else if(action==='eOverlay'){e.v.overlay=id;}
 else return false;
 if(!ok)toast('未完成：请查看材料、地点、岗位或等待条件。','warn');renderMenu();save();return true;
}
